import{c as n,j as e,r as t,b as s,d as a}from"./styles-C4Kc6xaY.js";import{L as i}from"./LegalPage-ROHn35QB.js";const r=[{id:"summary",title:"Summary",body:e.jsxs("ul",{className:"checks",children:[e.jsx("li",{children:"Oobli only reads SMS from financial senders (like M-Pesa and banks). Everything else is skipped on your phone."}),e.jsx("li",{children:"We store your transactions so you can see them on any device, locked to your account."}),e.jsx("li",{children:"We never sell your data and we don't show ads."}),e.jsx("li",{children:"You can ask us to delete everything at any time."})]})},{id:"collect",title:"What we collect",body:e.jsxs(e.Fragment,{children:[e.jsxs("p",{children:[e.jsx("b",{children:"Account details:"})," your name, email address and password (stored as a secure hash by our backend provider), plus app settings such as your monthly income estimate, focus goal and theme."]}),e.jsxs("p",{children:[e.jsx("b",{children:"Financial SMS:"})," with your permission, the app reads your SMS inbox ",e.jsx("b",{children:"on your phone"})," and keeps only messages from known financial senders. From each one it extracts the amount, direction (in or out), merchant or sender name, M-Pesa product, date, reference code and balance. The text of that financial message is saved with the transaction so you can check it later. Personal conversations are never read into the app or uploaded."]}),e.jsxs("p",{children:[e.jsx("b",{children:"Things you add:"})," manual transactions, notes, category corrections, plans and savings goals."]}),e.jsxs("p",{children:[e.jsx("b",{children:"Technical data:"})," basic logs (such as error messages and request times) needed to keep the Service secure and working."]})]})},{id:"use",title:"How we use it",body:e.jsxs("ul",{children:[e.jsx("li",{children:"To show your transactions, charts, plans, goals and monthly Wrapped."}),e.jsx("li",{children:"To categorise transactions, remembering the corrections you make for each merchant."}),e.jsx("li",{children:'To generate "Oobli says…" insights, plans and recaps.'}),e.jsx("li",{children:"To secure the Service, prevent abuse and fix problems."})]})},{id:"ai",title:"Artificial intelligence",body:e.jsxs(e.Fragment,{children:[e.jsx("p",{children:"Oobli first uses rules on your phone. Only when those can't decide does it ask our AI service, which runs on our servers and uses Google's Gemini models. What is sent:"}),e.jsxs("ul",{children:[e.jsxs("li",{children:[e.jsx("b",{children:"Categorising:"})," the merchant name, amount, M-Pesa product and direction of the transactions being sorted."]}),e.jsxs("li",{children:[e.jsx("b",{children:"Unrecognised messages:"})," the text of a financial SMS that our parser could not read."]}),e.jsxs("li",{children:[e.jsx("b",{children:"Insights, plans and Wrapped:"})," summaries such as category totals and trends, not your whole message history."]})]}),e.jsx("p",{children:"Requests are sent only for signed-in users, and Google processes them under its Gemini API terms. AI suggestions can be wrong, and you can always correct them."})]})},{id:"storage",title:"Where your data is stored",body:e.jsx("p",{children:"Your account and transactions are stored with Appwrite Cloud in its Singapore region. Each record is restricted so that only your account can read or change it. Data is encrypted in transit (HTTPS). Because our servers are outside Kenya, we rely on the safeguards the Data Protection Act, 2019 requires for cross-border transfers."})},{id:"share",title:"Who we share it with",body:e.jsxs(e.Fragment,{children:[e.jsx("p",{children:"We share data only with service providers that help us run Oobli, and only as needed:"}),e.jsxs("ul",{children:[e.jsxs("li",{children:[e.jsx("b",{children:"Appwrite"}),": authentication, database and server functions."]}),e.jsxs("li",{children:[e.jsx("b",{children:"Google (Gemini API)"}),": AI categorisation and insights, as described above."]})]}),e.jsx("p",{children:"We may disclose information if the law requires it. We do not sell personal data, and we do not share it with advertisers, lenders or data brokers."})]})},{id:"device",title:"Permissions and data on your device",body:e.jsxs("p",{children:["Oobli asks for ",e.jsx("b",{children:"SMS (read)"})," permission to import financial messages, and ",e.jsx("b",{children:"Internet"})," to sync. You can turn SMS access off in Settings at any time and still add transactions by hand. The app keeps a small cache on your phone, such as your session and settings. Signing out clears it."]})},{id:"retention",title:"How long we keep it",body:e.jsx("p",{children:"We keep your data while your account is active. If you ask us to delete your account, we delete your profile, transactions, rules, plans and goals within 30 days, except for anything we must keep by law. Backups are overwritten on a rolling basis."})},{id:"rights",title:"Your rights",body:e.jsxs(e.Fragment,{children:[e.jsxs("p",{children:["Under Kenya's Data Protection Act, 2019 you can ask to access, correct or delete your personal data, object to or restrict processing, and withdraw consent (for example, by turning off SMS access). To make a request, email ",e.jsx("a",{href:a,children:s}),". We will respond within the time the law requires."]}),e.jsx("p",{children:"If you're unhappy with how we handle your data, you can complain to the Office of the Data Protection Commissioner (ODPC)."})]})},{id:"children",title:"Children",body:e.jsx("p",{children:"Oobli is for adults aged 18 and over. We don't knowingly collect data from children. If you believe a child has used Oobli, contact us and we'll delete the account."})},{id:"changes",title:"Changes to this policy",body:e.jsx("p",{children:"If we change how we use your data in a significant way, we'll tell you in the app before the change applies. The date at the top shows when this policy was last updated."})},{id:"contact",title:"Contact",body:e.jsxs("p",{children:["Questions about privacy? Email ",e.jsx("a",{href:a,children:s}),"."]})}];n(document.getElementById("root")).render(e.jsx(t.StrictMode,{children:e.jsx(i,{title:"Privacy Policy",intro:"Your money messages are personal. This policy explains exactly what Oobli reads, what it stores, what our AI sees and the control you have.",sections:r})}));
